(() => {
    'use strict';

    const clamp = (value, min, max) =>
        Math.min(max, Math.max(min, value));

    function median(values) {
        if (!values.length) return 0;
        const sorted = [...values].sort((a, b) => a - b);
        const middle = Math.floor(sorted.length / 2);
        return sorted.length % 2
            ? sorted[middle]
            : (sorted[middle - 1] + sorted[middle]) / 2;
    }

    function featureFromCanvas(canvas) {
        const context =
            canvas.getContext(
                '2d',
                {
                    alpha: false,
                    willReadFrequently:
                        true
                }
            );

        const {
            width,
            height
        } = canvas;

        const data =
            context.getImageData(
                0,
                0,
                width,
                height
            ).data;

        const microW = 48;
        const microH = 27;

        const micro =
            new Uint8Array(
                microW *
                microH
            );

        const histLuma =
            new Float32Array(16);

        const histRgb =
            new Float32Array(24);

        let sum = 0;
        let darkPixels = 0;
        let veryDarkPixels = 0;

        for (
            let my = 0;
            my < microH;
            my += 1
        ) {
            const sourceY =
                Math.min(
                    height - 1,
                    Math.floor(
                        (
                            my + .5
                        ) *
                        height /
                        microH
                    )
                );

            for (
                let mx = 0;
                mx < microW;
                mx += 1
            ) {
                const sourceX =
                    Math.min(
                        width - 1,
                        Math.floor(
                            (
                                mx + .5
                            ) *
                            width /
                            microW
                        )
                    );

                const index =
                    (
                        sourceY *
                        width +
                        sourceX
                    ) * 4;

                const r =
                    data[index];

                const g =
                    data[index + 1];

                const b =
                    data[index + 2];

                const y =
                    (
                        77 * r +
                        150 * g +
                        29 * b
                    ) >> 8;

                micro[
                    my *
                        microW +
                    mx
                ] = y;

                histLuma[
                    Math.min(
                        15,
                        y >> 4
                    )
                ] += 1;

                histRgb[
                    Math.min(
                        7,
                        r >> 5
                    )
                ] += 1;

                histRgb[
                    8 +
                    Math.min(
                        7,
                        g >> 5
                    )
                ] += 1;

                histRgb[
                    16 +
                    Math.min(
                        7,
                        b >> 5
                    )
                ] += 1;

                sum += y;

                if (y < 64) {
                    darkPixels += 1;
                }

                if (y < 28) {
                    veryDarkPixels +=
                        1;
                }
            }
        }

        const pixelCount =
            micro.length;

        for (
            let index = 0;
            index <
                histLuma.length;
            index += 1
        ) {
            histLuma[index] /=
                pixelCount;
        }

        for (
            let index = 0;
            index <
                histRgb.length;
            index += 1
        ) {
            histRgb[index] /=
                pixelCount * 3;
        }

        const mean =
            sum /
            pixelCount;

        const darkRatio =
            darkPixels /
            pixelCount;

        const veryDarkRatio =
            veryDarkPixels /
            pixelCount;

        const lowLight =
            mean <= 78 &&
            darkRatio >= .52;

        return {
            micro,
            microW,
            microH,
            histLuma,
            histRgb,
            mean,
            darkRatio,
            veryDarkRatio,
            lowLight
        };
    }

    function isLowLightFeature(
        feature
    ) {
        const value =
            feature?.feature ||
            feature;

        if (!value) {
            return false;
        }

        if (
            typeof value.lowLight ===
            'boolean'
        ) {
            return value.lowLight;
        }

        return (
            Number(
                value.mean
            ) <= 78 &&
            Number(
                value.darkRatio
            ) >= .52
        );
    }

    function compareFeatures(
        first,
        second,
        allowShift = true
    ) {
        const a =
            first.feature ||
            first;

        const b =
            second.feature ||
            second;

        const width =
            a.microW;

        const height =
            a.microH;

        const meanOffset =
            b.mean -
            a.mean;

        function structuralAt(
            dx,
            dy
        ) {
            let weightedDiff = 0;
            let changedWeight = 0;
            let totalWeight = 0;

            for (
                let y = 0;
                y < height;
                y += 1
            ) {
                const by =
                    y + dy;

                if (
                    by < 0 ||
                    by >= height
                ) {
                    continue;
                }

                for (
                    let x = 0;
                    x < width;
                    x += 1
                ) {
                    const bx =
                        x + dx;

                    if (
                        bx < 0 ||
                        bx >= width
                    ) {
                        continue;
                    }

                    const edge =
                        x < 3 ||
                        x >=
                            width - 3 ||
                        y >=
                            Math.floor(
                                height *
                                .84
                            );

                    const weight =
                        edge
                            ? .2
                            : 1;

                    const difference =
                        Math.abs(
                            (
                                b.micro[
                                    by *
                                        width +
                                    bx
                                ] -
                                a.micro[
                                    y *
                                        width +
                                    x
                                ]
                            ) -
                            meanOffset
                        );

                    weightedDiff +=
                        difference *
                        weight;

                    if (
                        difference >
                        28
                    ) {
                        changedWeight +=
                            weight;
                    }

                    totalWeight +=
                        weight;
                }
            }

            return {
                structural:
                    totalWeight
                        ? weightedDiff /
                            (
                                totalWeight *
                                255
                            )
                        : 0,

                changed:
                    totalWeight
                        ? changedWeight /
                            totalWeight
                        : 0
            };
        }

        let spatial =
            structuralAt(
                0,
                0
            );

        let histL1 = 0;

        for (
            let index = 0;
            index <
                a.histLuma.length;
            index += 1
        ) {
            histL1 +=
                Math.abs(
                    a.histLuma[index] -
                    b.histLuma[index]
                );
        }

        let rgbL1 = 0;

        for (
            let index = 0;
            index <
                a.histRgb.length;
            index += 1
        ) {
            rgbL1 +=
                Math.abs(
                    a.histRgb[index] -
                    b.histRgb[index]
                );
        }

        const histogram =
            clamp(
                (
                    histL1 / 2
                ) * .62 +
                (
                    rgbL1 / 2
                ) * .38,
                0,
                1
            );

        const brightness =
            Math.abs(
                meanOffset
            ) /
            255;

        const fromLowLight =
            isLowLightFeature(
                a
            );

        const toLowLight =
            isLowLightFeature(
                b
            );

        const lowLightTransition =
            fromLowLight !==
                toLowLight &&
            brightness >= .10;

        const transitionBoost =
            lowLightTransition
                ? clamp(
                    (
                        brightness -
                        .08
                    ) /
                        .28,
                    0,
                    1
                )
                : 0;

        const initialScore =
            .40 *
                spatial.structural +
            .27 *
                spatial.changed +
            .24 *
                histogram +
            .04 *
                brightness +
            .05 *
                transitionBoost;

        if (
            allowShift &&
            histogram < .14 &&
            initialScore > .075 &&
            initialScore < .34
        ) {
            for (
                const [dx, dy]
                of [
                    [-1, 0],
                    [1, 0],
                    [0, -1],
                    [0, 1],
                    [-1, -1],
                    [1, 1]
                ]
            ) {
                const shifted =
                    structuralAt(
                        dx,
                        dy
                    );

                const shiftedValue =
                    .6 *
                        shifted
                            .structural +
                    .4 *
                        shifted
                            .changed;

                const currentValue =
                    .6 *
                        spatial
                            .structural +
                    .4 *
                        spatial
                            .changed;

                if (
                    shiftedValue <
                    currentValue
                ) {
                    spatial =
                        shifted;
                }
            }
        }

        const score =
            clamp(
                .40 *
                    spatial
                        .structural +
                .27 *
                    spatial
                        .changed +
                .24 *
                    histogram +
                .04 *
                    brightness +
                .05 *
                    transitionBoost,
                0,
                1
            );

        return {
            score,
            histogram,
            structural:
                spatial.structural,
            changed:
                spatial.changed,
            brightness,
            fromMean:
                a.mean,
            toMean:
                b.mean,
            fromLowLight,
            toLowLight,
            lowLightTransition
        };
    }

    function adaptiveThreshold(history, config) {
        const recent = history.slice(-25);
        if (recent.length < 7) return config.absoluteCut;
        const center = median(recent);
        const deviation = median(recent.map(value => Math.abs(value - center)));
        const sigma = Math.max(.01, 1.4826 * deviation);
        return clamp(Math.max(config.absoluteCut, center + config.adaptiveK * sigma), config.absoluteCut, config.maxThreshold);
    }

    function passesStructuralGate(comparison, gate) {
        return comparison.histogram >= gate.histogram || comparison.structural >= gate.structural || comparison.changed >= gate.changed;
    }

    function detectSuspiciousRanges(
        scan,
        config,
        duration
    ) {
        const ranges = [];

        const {
            pairs,
            samples,
            step
        } = scan;

        pairs.forEach(
            (
                pair,
                index
            ) => {
                const previous =
                    pairs[
                        index - 1
                    ]?.score || 0;

                const next =
                    pairs[
                        index + 1
                    ]?.score || 0;

                const localPeak =
                    pair.score >=
                        previous &&
                    pair.score >=
                        next;

                if (
                    pair.hard ||
                    (
                        localPeak &&
                        pair.score >=
                            pair.threshold *
                            .78 &&
                        passesStructuralGate(
                            pair,
                            config.hardGate
                        )
                    )
                ) {
                    ranges.push({
                        start:
                            pair.start -
                            step,
                        end:
                            pair.end +
                            step,
                        confidence:
                            pair.score,
                        type:
                            'hard'
                    });
                }
            }
        );

        for (
            let index = 2;
            index <
                samples.length - 2;
            index += 1
        ) {
            const before =
                samples[
                    index - 2
                ];

            const beforeNear =
                samples[
                    index - 1
                ];

            const afterNear =
                samples[
                    index + 1
                ];

            const after =
                samples[
                    index + 2
                ];

            const beforeLow =
                isLowLightFeature(
                    before
                );

            const afterLow =
                isLowLightFeature(
                    after
                );

            if (
                beforeLow ===
                afterLow
            ) {
                continue;
            }

            const stableBefore =
                isLowLightFeature(
                    beforeNear
                ) === beforeLow;

            const stableAfter =
                isLowLightFeature(
                    afterNear
                ) === afterLow;

            const luminanceChange =
                Math.abs(
                    (
                        after.feature
                            .mean -
                        before.feature
                            .mean
                    ) /
                    255
                );

            if (
                stableBefore &&
                stableAfter &&
                luminanceChange >=
                    .15
            ) {
                ranges.push({
                    start:
                        before.time -
                        step *
                        .35,
                    end:
                        after.time +
                        step *
                        .35,
                    confidence:
                        Math.max(
                            .18,
                            luminanceChange
                        ),
                    type:
                        'low-light'
                });
            }
        }

        let run = [];

        const flushRun = () => {
            if (
                run.length >= 3
            ) {
                const changedPairs =
                    run.filter(
                        pair =>
                            pair.score >=
                            config
                                .gradualFloor
                    );

                const sum =
                    changedPairs.reduce(
                        (
                            total,
                            pair
                        ) =>
                            total +
                            pair.score,
                        0
                    );

                const firstSample =
                    samples.find(
                        sample =>
                            sample.time >=
                            run[0]
                                .start -
                            .001
                    ) ||
                    samples[0];

                const lastSample =
                    [
                        ...samples
                    ]
                        .reverse()
                        .find(
                            sample =>
                                sample.time <=
                                run[
                                    run.length -
                                    1
                                ].end +
                                    .001
                        ) ||
                    samples[
                        samples.length -
                        1
                    ];

                const endpointComparison =
                    firstSample &&
                    lastSample
                        ? compareFeatures(
                            firstSample,
                            lastSample,
                            false
                        )
                        : null;

                const endpoint =
                    endpointComparison
                        ?.score || 0;

                const duration =
                    run[
                        run.length -
                        1
                    ].end -
                    run[0].start;

                const gradualPass =
                    changedPairs.length >=
                        3 &&
                    sum >=
                        config.gradualSum &&
                    endpoint >=
                        config.endpointGate;

                const lowLightFade =
                    endpointComparison
                        ?.lowLightTransition &&
                    endpointComparison
                        .brightness >=
                        .14;

                if (
                    (
                        gradualPass ||
                        lowLightFade
                    ) &&
                    duration <=
                        Math.max(
                            2.8,
                            step * 5
                        )
                ) {
                    ranges.push({
                        start:
                            run[0].start -
                            step * .5,
                        end:
                            run[
                                run.length -
                                1
                            ].end +
                            step * .5,
                        confidence:
                            Math.max(
                                sum /
                                    Math.max(
                                        1,
                                        run.length
                                    ),
                                endpoint
                            ),
                        type:
                            lowLightFade
                                ? 'low-light'
                                : 'gradual'
                    });
                }
            }

            run = [];
        };

        pairs.forEach(
            pair => {
                if (
                    pair.score >=
                    config.gradualFloor
                ) {
                    run.push(
                        pair
                    );
                } else {
                    flushRun();
                }
            }
        );

        flushRun();

        const normalized =
            ranges
                .map(
                    range => ({
                        ...range,
                        start:
                            clamp(
                                range.start,
                                0,
                                duration -
                                    .05
                            ),
                        end:
                            clamp(
                                range.end,
                                .05,
                                duration -
                                    .04
                            )
                    })
                )
                .sort(
                    (a, b) =>
                        a.start -
                        b.start
                );

        const merged = [];

        normalized.forEach(
            range => {
                const previous =
                    merged[
                        merged.length -
                        1
                    ];

                if (
                    previous &&
                    range.start <=
                        previous.end +
                        config.fineStep *
                        2
                ) {
                    previous.end =
                        Math.max(
                            previous.end,
                            range.end
                        );

                    previous.confidence =
                        Math.max(
                            previous
                                .confidence,
                            range
                                .confidence
                        );

                    if (
                        range.type ===
                        'hard'
                    ) {
                        previous.type =
                            'hard';
                    } else if (
                        previous.type !==
                            'hard' &&
                        range.type ===
                            'low-light'
                    ) {
                        previous.type =
                            'low-light';
                    }
                } else {
                    merged.push({
                        ...range
                    });
                }
            }
        );

        return merged;
    }

    function normalizeBoundaries(candidates, config, duration) {
        const filtered = candidates
            .filter(item => item.time > .08 && item.time < duration - .08)
            .sort((a, b) => b.confidence - a.confidence);
        const retained = [];
        for (const candidate of filtered) {
            if (!retained.some(item => Math.abs(item.time - candidate.time) < config.minGap)) retained.push(candidate);
        }
        retained.sort((a, b) => a.time - b.time);
        if (retained.length > config.maxClips - 1) {
            const strongest = [...retained].sort((a, b) => b.confidence - a.confidence).slice(0, config.maxClips - 1);
            strongest.sort((a, b) => a.time - b.time);
            return strongest;
        }
        return retained;
    }

    function averageNumbers(values) {
        const valid =
            values.filter(
                value =>
                    Number.isFinite(
                        value
                    )
            );

        if (!valid.length) {
            return 0;
        }

        return valid.reduce(
            (
                total,
                value
            ) =>
                total + value,
            0
        ) / valid.length;
    }

    function boundarySpatialEvidence(
        first,
        second
    ) {
        const a =
            first?.feature ||
            first;

        const b =
            second?.feature ||
            second;

        if (
            !a?.micro ||
            !b?.micro ||
            !a.microW ||
            !a.microH ||
            a.microW !== b.microW ||
            a.microH !== b.microH
        ) {
            return {
                robust: 1,
                coverage: 1,
                strongCoverage: 1,
                localization: 0
            };
        }

        const width =
            a.microW;

        const height =
            a.microH;

        const meanOffset =
            Number(
                b.mean || 0
            ) -
            Number(
                a.mean || 0
            );

        const tileColumns = 6;
        const tileRows = 4;

        const inspectShift =
            (
                dx,
                dy
            ) => {
                const tileSum =
                    new Float64Array(
                        tileColumns *
                        tileRows
                    );

                const tileWeight =
                    new Float64Array(
                        tileColumns *
                        tileRows
                    );

                for (
                    let y = 1;
                    y < height - 1;
                    y += 1
                ) {
                    const by =
                        y + dy;

                    if (
                        by < 1 ||
                        by >= height - 1
                    ) {
                        continue;
                    }

                    for (
                        let x = 1;
                        x < width - 1;
                        x += 1
                    ) {
                        const bx =
                            x + dx;

                        if (
                            bx < 1 ||
                            bx >= width - 1
                        ) {
                            continue;
                        }

                        const tileX =
                            Math.min(
                                tileColumns - 1,
                                Math.floor(
                                    x *
                                    tileColumns /
                                    width
                                )
                            );

                        const tileY =
                            Math.min(
                                tileRows - 1,
                                Math.floor(
                                    y *
                                    tileRows /
                                    height
                                )
                            );

                        const tileIndex =
                            tileY *
                            tileColumns +
                            tileX;

                        let weight = 1;

                        if (
                            tileY ===
                            tileRows - 1
                        ) {
                            weight *= .42;
                        }

                        if (
                            tileX === 0 ||
                            tileX ===
                                tileColumns - 1
                        ) {
                            weight *= .72;
                        }

                        const difference =
                            Math.abs(
                                (
                                    b.micro[
                                        by *
                                        width +
                                        bx
                                    ] -
                                    a.micro[
                                        y *
                                        width +
                                        x
                                    ]
                                ) -
                                meanOffset
                            ) /
                            255;

                        tileSum[
                            tileIndex
                        ] +=
                            difference *
                            weight;

                        tileWeight[
                            tileIndex
                        ] +=
                            weight;
                    }
                }

                const values =
                    [...tileSum].map(
                        (
                            sum,
                            index
                        ) =>
                            tileWeight[
                                index
                            ]
                                ? sum /
                                    tileWeight[
                                        index
                                    ]
                                : 0
                    );

                const ordered =
                    [...values].sort(
                        (
                            firstValue,
                            secondValue
                        ) =>
                            firstValue -
                            secondValue
                    );

                const trimCount =
                    Math.min(
                        Math.floor(
                            ordered.length *
                            .20
                        ),
                        Math.max(
                            0,
                            ordered.length -
                            4
                        )
                    );

                const robustValues =
                    trimCount
                        ? ordered.slice(
                            0,
                            ordered.length -
                                trimCount
                        )
                        : ordered;

                const robust =
                    averageNumbers(
                        robustValues
                    );

                const coverage =
                    values.filter(
                        value =>
                            value >= .095
                    ).length /
                    Math.max(
                        1,
                        values.length
                    );

                const strongCoverage =
                    values.filter(
                        value =>
                            value >= .17
                    ).length /
                    Math.max(
                        1,
                        values.length
                    );

                const peak =
                    Math.max(
                        0,
                        ...values
                    );

                const localization =
                    clamp(
                        (
                            1 -
                            coverage
                        ) *
                        clamp(
                            peak /
                            Math.max(
                                .035,
                                robust *
                                2.6
                            ),
                            0,
                            1
                        ),
                        0,
                        1
                    );

                return {
                    robust,
                    coverage,
                    strongCoverage,
                    localization
                };
            };

        let best =
            inspectShift(
                0,
                0
            );

        for (
            const [dx, dy]
            of [
                [-1, 0],
                [1, 0],
                [0, -1],
                [0, 1],
                [-1, -1],
                [1, 1]
            ]
        ) {
            const shifted =
                inspectShift(
                    dx,
                    dy
                );

            const shiftedValue =
                shifted.robust *
                    .72 +
                shifted.coverage *
                    .20 +
                shifted.strongCoverage *
                    .08;

            const bestValue =
                best.robust *
                    .72 +
                best.coverage *
                    .20 +
                best.strongCoverage *
                    .08;

            if (
                shiftedValue <
                bestValue
            ) {
                best =
                    shifted;
            }
        }

        return best;
    }

    function qualityMetricsFromCanvas(canvas) {
        const context = canvas.getContext('2d', {
            alpha: false,
            willReadFrequently: true
        });

        const { width, height } = canvas;
        const image = context.getImageData(0, 0, width, height);
        const data = image.data;
        const luma = new Uint8Array(width * height);
        const histogram = new Float32Array(32);

        let sum = 0;
        let sumSquares = 0;
        let dark = 0;
        let bright = 0;
        let lowLightPixels = 0;
        let shadowPixels = 0;

        for (
            let index = 0, pixel = 0;
            index < data.length;
            index += 4, pixel += 1
        ) {
            const value =
                (
                    77 * data[index] +
                    150 * data[index + 1] +
                    29 * data[index + 2]
                ) >> 8;

            luma[pixel] = value;
            histogram[Math.min(31, value >> 3)] += 1;
            sum += value;
            sumSquares += value * value;

            if (value < 12) dark += 1;
            if (value > 246) bright += 1;
            if (
                value < 64
            ) {
                lowLightPixels += 1;
            }

            if (
                value < 32
            ) {
                shadowPixels += 1;
            }
        }

        const pixels = width * height;

        for (
            let index = 0;
            index < histogram.length;
            index += 1
        ) {
            histogram[index] /= pixels;
        }

        const mean =
            sum / pixels / 255;

        const lowLightRatio =
            lowLightPixels /
            pixels;

        const shadowRatio =
            shadowPixels /
            pixels;

        const lowLight =
            mean <= .30 &&
            lowLightRatio >= .52;

        const variance =
            Math.max(
                0,
                sumSquares / pixels -
                Math.pow(
                    sum / pixels,
                    2
                )
            );

        const contrast =
            clamp(
                Math.sqrt(variance) /
                    255 /
                    .22,
                0,
                1
            );

        let entropy = 0;

        histogram.forEach(
            probability => {
                if (probability > 0) {
                    entropy -=
                        probability *
                        Math.log2(
                            probability
                        );
                }
            }
        );

        entropy =
            clamp(
                entropy / 5,
                0,
                1
            );

        let laplacianSum = 0;
        let laplacianSquares = 0;
        let laplacianCount = 0;
        let gradientXEnergy = 0;
        let gradientYEnergy = 0;
        let edgeCount = 0;

        const sharpHeight =
            Math.floor(
                height * .85
            );

        const tileColumns = 4;
        const tileRows = 4;
        const tileCount =
            tileColumns *
            tileRows;

        const tileLapSum =
            new Float64Array(
                tileCount
            );

        const tileLapSquares =
            new Float64Array(
                tileCount
            );

        const tileLapCount =
            new Uint32Array(
                tileCount
            );

        for (
            let y = 1;
            y < sharpHeight - 1;
            y += 2
        ) {
            for (
                let x = 1;
                x < width - 1;
                x += 2
            ) {
                const center =
                    luma[
                        y * width + x
                    ];

                const gradientX =
                    luma[
                        y * width +
                        x + 1
                    ] -
                    luma[
                        y * width +
                        x - 1
                    ];

                const gradientY =
                    luma[
                        (y + 1) *
                            width +
                        x
                    ] -
                    luma[
                        (y - 1) *
                            width +
                        x
                    ];

                const laplacian =
                    4 * center -
                    luma[
                        y * width +
                        x - 1
                    ] -
                    luma[
                        y * width +
                        x + 1
                    ] -
                    luma[
                        (y - 1) *
                            width +
                        x
                    ] -
                    luma[
                        (y + 1) *
                            width +
                        x
                    ];

                laplacianSum +=
                    laplacian;

                laplacianSquares +=
                    laplacian *
                    laplacian;

                gradientXEnergy +=
                    gradientX *
                    gradientX;

                gradientYEnergy +=
                    gradientY *
                    gradientY;

                if (
                    Math.hypot(
                        gradientX,
                        gradientY
                    ) > 34
                ) {
                    edgeCount += 1;
                }

                laplacianCount += 1;

                const tileX =
                    Math.min(
                        tileColumns - 1,
                        Math.floor(
                            x /
                            width *
                            tileColumns
                        )
                    );

                const tileY =
                    Math.min(
                        tileRows - 1,
                        Math.floor(
                            y /
                            sharpHeight *
                            tileRows
                        )
                    );

                const tileIndex =
                    tileY *
                        tileColumns +
                    tileX;

                tileLapSum[
                    tileIndex
                ] += laplacian;

                tileLapSquares[
                    tileIndex
                ] +=
                    laplacian *
                    laplacian;

                tileLapCount[
                    tileIndex
                ] += 1;
            }
        }

        const normalizeSharpness =
            value =>
                clamp(
                    (
                        Math.log(
                            value + 1
                        ) -
                        Math.log(20)
                    ) /
                    (
                        Math.log(1200) -
                        Math.log(20)
                    ),
                    0,
                    1
                );

        const lapMean =
            laplacianCount
                ? laplacianSum /
                    laplacianCount
                : 0;

        const lapVariance =
            laplacianCount
                ? Math.max(
                    0,
                    laplacianSquares /
                        laplacianCount -
                        lapMean *
                        lapMean
                )
                : 0;

        const globalSharp =
            normalizeSharpness(
                lapVariance
            );

        const regionalSharpness =
            [];

        for (
            let index = 0;
            index < tileCount;
            index += 1
        ) {
            const count =
                tileLapCount[index];

            if (count < 12) {
                continue;
            }

            const average =
                tileLapSum[index] /
                count;

            const tileVariance =
                Math.max(
                    0,
                    tileLapSquares[index] /
                        count -
                        average *
                        average
                );

            regionalSharpness.push(
                normalizeSharpness(
                    tileVariance
                )
            );
        }

        regionalSharpness.sort(
            (a, b) => a - b
        );

        const regionalSharp =
            regionalSharpness.length
                ? regionalSharpness[
                    Math.floor(
                        (
                            regionalSharpness.length -
                            1
                        ) * .65
                    )
                ]
                : globalSharp;

        const sharp =
            clamp(
                .58 * regionalSharp +
                .42 * globalSharp,
                0,
                1
            );

        const regularExposure =
            clamp(
                (
                    mean - .05
                ) /
                    .15,
                0,
                1
            ) *
            clamp(
                (
                    .97 - mean
                ) /
                    .12,
                0,
                1
            );

        const lowLightExposure =
            clamp(
                (
                    mean - .015
                ) /
                    .18,
                0,
                1
            );

        const exposure =
            lowLight
                ? clamp(
                    .48 +
                        .52 *
                        lowLightExposure,
                    0,
                    1
                )
                : regularExposure;

        const clippedPenalty =
            lowLight
                ? clamp(
                    (
                        bright /
                        pixels
                    ) *
                        1.6 +
                    (
                        dark /
                        pixels
                    ) *
                        .16,
                    0,
                    .22
                )
                : clamp(
                    (
                        dark +
                        bright
                    ) /
                        pixels *
                        2.2,
                    0,
                    .42
                );

        const edgeDensity =
            laplacianCount
                ? edgeCount /
                    laplacianCount
                : 0;

        const gradientTotal =
            gradientXEnergy +
            gradientYEnergy;

        const directionalBias =
            gradientTotal
                ? Math.abs(
                    gradientXEnergy -
                    gradientYEnergy
                ) /
                    gradientTotal
                : 1;

        const motionBlur =
            clamp(
                .62 *
                    clamp(
                        (
                            .38 -
                            sharp
                        ) /
                            .38,
                        0,
                        1
                    ) +
                .23 *
                    clamp(
                        (
                            .055 -
                            edgeDensity
                        ) /
                            .055,
                        0,
                        1
                    ) +
                .15 *
                    directionalBias *
                    clamp(
                        (
                            .52 -
                            sharp
                        ) /
                            .52,
                        0,
                        1
                    ),
                0,
                1
            );

        const signature =
            new Uint8Array(
                16 * 9
            );

        for (
            let gy = 0;
            gy < 9;
            gy += 1
        ) {
            const cellTop =
                Math.floor(
                    gy *
                    height /
                    9
                );

            const cellBottom =
                Math.max(
                    cellTop + 1,
                    Math.floor(
                        (
                            gy + 1
                        ) *
                        height /
                        9
                    )
                );

            const stepY =
                Math.max(
                    1,
                    Math.floor(
                        (
                            cellBottom -
                            cellTop
                        ) /
                        4
                    )
                );

            for (
                let gx = 0;
                gx < 16;
                gx += 1
            ) {
                const cellLeft =
                    Math.floor(
                        gx *
                        width /
                        16
                    );

                const cellRight =
                    Math.max(
                        cellLeft + 1,
                        Math.floor(
                            (
                                gx + 1
                            ) *
                            width /
                            16
                        )
                    );

                const stepX =
                    Math.max(
                        1,
                        Math.floor(
                            (
                                cellRight -
                                cellLeft
                            ) /
                            4
                        )
                    );

                let cellSum = 0;
                let samples = 0;

                for (
                    let y = cellTop;
                    y < cellBottom;
                    y += stepY
                ) {
                    for (
                        let x = cellLeft;
                        x < cellRight;
                        x += stepX
                    ) {
                        cellSum +=
                            luma[
                                Math.min(
                                    height - 1,
                                    y
                                ) *
                                    width +
                                Math.min(
                                    width - 1,
                                    x
                                )
                            ];

                        samples += 1;
                    }
                }

                signature[
                    gy * 16 + gx
                ] =
                    samples
                        ? Math.round(
                            cellSum /
                            samples
                        )
                        : 0;
            }
        }

        const dHash =
            new Uint8Array(64);

        for (
            let gy = 0;
            gy < 8;
            gy += 1
        ) {
            const sy =
                Math.min(
                    height - 1,
                    Math.floor(
                        (
                            gy + .5
                        ) *
                        height /
                        8
                    )
                );

            for (
                let gx = 0;
                gx < 8;
                gx += 1
            ) {
                const leftX =
                    Math.min(
                        width - 1,
                        Math.floor(
                            (
                                gx + .35
                            ) *
                            width /
                            9
                        )
                    );

                const rightX =
                    Math.min(
                        width - 1,
                        Math.floor(
                            (
                                gx + 1.35
                            ) *
                            width /
                            9
                        )
                    );

                dHash[
                    gy * 8 + gx
                ] =
                    luma[
                        sy * width +
                        leftX
                    ] >
                    luma[
                        sy * width +
                        rightX
                    ]
                        ? 1
                        : 0;
            }
        }

        return {
            histogram,
            signature,
            dHash,
            sharp,
            exposure,
            entropy,
            contrast,
            clippedPenalty,
            mean,
            lowLight,
            lowLightRatio,
            shadowRatio,
            edgeDensity,
            directionalBias,
            motionBlur
        };
    }

    function frameDistances(
        first,
        second
    ) {
        let hamming = 0;

        const hashLength =
            Math.min(
                first.dHash.length,
                second.dHash.length
            );

        for (
            let index = 0;
            index < hashLength;
            index += 1
        ) {
            if (
                first.dHash[index] !==
                second.dHash[index]
            ) {
                hamming += 1;
            }
        }

        let histogram = 0;

        const histogramLength =
            Math.min(
                first.histogram.length,
                second.histogram.length
            );

        for (
            let index = 0;
            index <
                histogramLength;
            index += 1
        ) {
            histogram +=
                Math.abs(
                    first.histogram[index] -
                    second.histogram[index]
                );
        }

        histogram /= 2;

        const signatureLength =
            Math.min(
                first.signature.length,
                second.signature.length
            );

        let firstMean = 0;
        let secondMean = 0;

        for (
            let index = 0;
            index <
                signatureLength;
            index += 1
        ) {
            firstMean +=
                first.signature[index];

            secondMean +=
                second.signature[index];
        }

        firstMean /=
            Math.max(
                1,
                signatureLength
            );

        secondMean /=
            Math.max(
                1,
                signatureLength
            );

        const brightnessOffset =
            secondMean -
            firstMean;

        let signatureRaw = 0;
        let signatureNormalized = 0;

        let overlayRaw = 0;
        let overlayNormalized = 0;
        let overlayWeight = 0;

        const signatureColumns = 16;

        for (
            let index = 0;
            index <
                signatureLength;
            index += 1
        ) {
            const firstValue =
                first.signature[index];

            const secondValue =
                second.signature[index];

            const rawDifference =
                Math.abs(
                    firstValue -
                    secondValue
                );

            const normalizedDifference =
                Math.abs(
                    firstValue -
                    (
                        secondValue -
                        brightnessOffset
                    )
                );

            signatureRaw +=
                rawDifference;

            signatureNormalized +=
                normalizedDifference;

            const row =
                Math.floor(
                    index /
                    signatureColumns
                );

            const column =
                index %
                signatureColumns;

            let weight = 1;

            const likelySubtitleZone =
                row >= 4 &&
                row <= 7 &&
                column >= 3 &&
                column <= 12;

            if (
                likelySubtitleZone
            ) {
                weight *= .30;
            }

            if (
                row === 0
            ) {
                weight *= .55;
            }

            if (
                row >= 8
            ) {
                weight *= .38;
            }

            if (
                column === 0 ||
                column ===
                    signatureColumns - 1
            ) {
                weight *= .72;
            }

            overlayRaw +=
                rawDifference *
                weight;

            overlayNormalized +=
                normalizedDifference *
                weight;

            overlayWeight +=
                weight;
        }

        signatureRaw /=
            Math.max(
                1,
                signatureLength
            ) * 255;

        signatureNormalized /=
            Math.max(
                1,
                signatureLength
            ) * 255;

        const signature =
            Math.min(
                signatureRaw,
                signatureNormalized *
                    1.08
            );

        const overlaySignature =
            Math.min(
                overlayRaw,
                overlayNormalized *
                    1.08
            ) /
            (
                Math.max(
                    1,
                    overlayWeight
                ) *
                255
            );

        const visual =
            clamp(
                (
                    hamming /
                    Math.max(
                        1,
                        hashLength
                    )
                ) * .30 +
                histogram * .18 +
                signature * .27 +
                overlaySignature *
                    .25,
                0,
                1
            );

        return {
            hamming,
            histogram,
            signature,
            overlaySignature,
            visual
        };
    }

    function frameLimitForClip(
        clip,
        config,
        frames = []
    ) {
        const maximum =
            Math.max(
                1,
                Number(
                    config.framesPerClip
                ) || 10
            );

        const duration =
            Math.max(
                .01,
                Number(
                    clip?.end
                ) -
                Number(
                    clip?.start
                )
            );

        let target;

        if (duration <= .75) {
            target = 2;
        } else if (
            duration <= 1.35
        ) {
            target = 3;
        } else if (
            duration <= 2.5
        ) {
            target = 5;
        } else if (
            duration <= 4
        ) {
            target = 6;
        } else if (
            duration <= 6.5
        ) {
            target = 8;
        } else if (
            duration <= 10
        ) {
            target = 10;
        } else if (
            duration <= 16
        ) {
            target = 12;
        } else {
            target = 14;
        }

        return Math.min(
            maximum,
            target
        );
    }

    function frameAppearanceSimilarity(
        first,
        second,
        config
    ) {
        const distance =
            frameDistances(
                first,
                second
            );

        const duplicate =
            config.duplicate ||
            {};

        const visualScale =
            Math.max(
                .15,
                Number(
                    duplicate.visual
                ) *
                    1.95 ||
                .17
            );

        const overlayScale =
            Math.max(
                .105,
                Number(
                    duplicate
                        .overlaySignature
                ) *
                    2.10 ||
                .12
            );

        const histogramScale =
            Math.max(
                .16,
                Number(
                    duplicate.histogram
                ) *
                    1.65 ||
                .18
            );

        const hammingScale =
            Math.max(
                22,
                (
                    Number(
                        duplicate.hamming
                    ) || 9
                ) +
                    18
            );

        const visualSimilarity =
            1 -
            clamp(
                distance.visual /
                    visualScale,
                0,
                1
            );

        const overlaySimilarity =
            1 -
            clamp(
                distance
                    .overlaySignature /
                    overlayScale,
                0,
                1
            );

        const histogramSimilarity =
            1 -
            clamp(
                distance.histogram /
                    histogramScale,
                0,
                1
            );

        const hashSimilarity =
            1 -
            clamp(
                distance.hamming /
                    hammingScale,
                0,
                1
            );

        const score =
            clamp(
                overlaySimilarity *
                    .42 +
                visualSimilarity *
                    .25 +
                histogramSimilarity *
                    .20 +
                hashSimilarity *
                    .13,
                0,
                1
            );

        return {
            score,
            distance
        };
    }

    function framesShareSameLook(
        first,
        second,
        config
    ) {
        const {
            score,
            distance
        } =
            frameAppearanceSimilarity(
                first,
                second,
                config
            );

        const duplicate =
            config.duplicate ||
            {};

        const overlayAwareMatch =
            distance.overlaySignature <=
                Math.max(
                    .095,
                    Number(
                        duplicate
                            .overlaySignature
                    ) *
                        1.75 ||
                    .11
                ) &&
            distance.histogram <=
                Math.max(
                    .15,
                    Number(
                        duplicate.histogram
                    ) *
                        1.40 ||
                    .17
                ) &&
            distance.hamming <=
                (
                    Number(
                        duplicate.hamming
                    ) || 9
                ) +
                    17;

        const directMatch =
            distance.visual <=
                Math.max(
                    .125,
                    Number(
                        duplicate.visual
                    ) *
                        1.48 ||
                    .14
                ) &&
            distance.histogram <=
                Math.max(
                    .16,
                    Number(
                        duplicate.histogram
                    ) *
                        1.48 ||
                    .17
                );

        return (
            score >= .67 ||
            overlayAwareMatch ||
            directMatch
        );
    }

    function clusterFramesByAppearance(
        frames,
        config
    ) {
        const ordered =
            [...frames].sort(
                (a, b) =>
                    b.quality -
                    a.quality
            );

        const clusters = [];

        for (
            const frame
            of ordered
        ) {
            let bestCluster =
                null;

            let bestSimilarity =
                -Infinity;

            for (
                const cluster
                of clusters
            ) {
                const comparison =
                    frameAppearanceSimilarity(
                        frame,
                        cluster.representative,
                        config
                    );

                if (
                    framesShareSameLook(
                        frame,
                        cluster.representative,
                        config
                    ) &&
                    comparison.score >
                        bestSimilarity
                ) {
                    bestCluster =
                        cluster;

                    bestSimilarity =
                        comparison.score;
                }
            }

            if (!bestCluster) {
                clusters.push({
                    representative:
                        frame,

                    frames: [
                        frame
                    ]
                });

                continue;
            }

            bestCluster.frames.push(
                frame
            );

            if (
                frame.quality >
                bestCluster
                    .representative
                    .quality
            ) {
                bestCluster
                    .representative =
                    frame;
            }
        }

        clusters.forEach(
            cluster => {
                cluster.frames.sort(
                    (a, b) =>
                        b.quality -
                        a.quality
                );
            }
        );

        return clusters;
    }

    function isUsableFrameCandidate(
        frame,
        bestFrame
    ) {
        if (!frame) {
            return false;
        }

        if (
            frame ===
            bestFrame
        ) {
            return true;
        }

        const metrics =
            frame.metrics ||
            {};

        const sharp =
            Number(
                metrics.sharp
            ) || 0;

        const motionBlur =
            Number(
                metrics.motionBlur
            ) || 0;

        const severeBlur =
            motionBlur >= .90 &&
            sharp < .24;

        const unusablySoft =
            sharp < .15 &&
            motionBlur >= .62;

        if (
            severeBlur ||
            unusablySoft
        ) {
            return false;
        }

        const bestQuality =
            Number(
                bestFrame?.quality
            ) || 0;

        const relativeFloor =
            Math.max(
                .16,
                bestQuality -
                    .42
            );

        return (
            frame.quality >=
            relativeFloor
        );
    }

    function frameSceneAffinity(
        first,
        second,
        config
    ) {
        const distance =
            frameDistances(
                first,
                second
            );

        const duplicate =
            config.duplicate || {};

        const visualScale =
            Math.max(
                .11,
                (
                    Number(
                        duplicate
                            .crossClipVisual
                    ) || .12
                ) *
                2.20
            );

        const histogramScale =
            Math.max(
                .13,
                (
                    Number(
                        duplicate
                            .crossClipHistogram
                    ) || .14
                ) *
                1.95
            );

        const overlayScale =
            Math.max(
                .09,
                (
                    Number(
                        duplicate
                            .overlaySignature
                    ) || .065
                ) *
                2.45
            );

        const hammingScale =
            Math.max(
                18,
                (
                    Number(
                        duplicate.hamming
                    ) || 9
                ) +
                22
            );

        return clamp(
            .29 *
                (
                    1 -
                    clamp(
                        distance.visual /
                        visualScale,
                        0,
                        1
                    )
                ) +

            .19 *
                (
                    1 -
                    clamp(
                        distance.histogram /
                        histogramScale,
                        0,
                        1
                    )
                ) +

            .37 *
                (
                    1 -
                    clamp(
                        distance
                            .overlaySignature /
                        overlayScale,
                        0,
                        1
                    )
                ) +

            .15 *
                (
                    1 -
                    clamp(
                        distance.hamming /
                        hammingScale,
                        0,
                        1
                    )
                ),

            0,
            1
        );
    }

    function reciprocalClipAffinity(
        leftFrames,
        rightFrames,
        config
    ) {
        if (
            !leftFrames.length ||
            !rightFrames.length
        ) {
            return 0;
        }

        const averageBest =
            (
                source,
                target
            ) =>
                averageNumbers(
                    source.map(
                        sourceFrame =>
                            Math.max(
                                ...target.map(
                                    targetFrame =>
                                        frameSceneAffinity(
                                            sourceFrame,
                                            targetFrame,
                                            config
                                        )
                                )
                            )
                    )
                );

        return (
            averageBest(
                leftFrames,
                rightFrames
            ) +
            averageBest(
                rightFrames,
                leftFrames
            )
        ) / 2;
    }

    function candidateTimesForClip(
        clip,
        config
    ) {
        const duration =
            Math.max(
                .01,
                clip.end -
                clip.start
            );

        const transitionSafeStart =
            clip.index > 0 &&
            Number.isFinite(
                clip.transitionEnd
            )
                ? clip.transitionEnd +
                    .045
                : clip.start +
                    .045;

        const safeStart =
            clamp(
                Math.max(
                    clip.start +
                        .045,
                    transitionSafeStart
                ),
                clip.start,
                clip.end
            );

        const safeEnd =
            clamp(
                clip.end -
                    .045,
                safeStart,
                clip.end
            );

        const usableDuration =
            Math.max(
                0,
                safeEnd -
                safeStart
            );

        if (
            usableDuration <= .05
        ) {
            return [
                clamp(
                    clip.start +
                        duration * .5,
                    clip.start,
                    Math.max(
                        clip.start,
                        clip.end -
                            .01
                    )
                )
            ];
        }

        const baseBudget =
            Math.max(
                2,
                Number(
                    config.candidateBudget
                ) || 6
            );

        const maximumBudget =
            Math.max(
                baseBudget,
                Number(
                    config
                        .maxCandidateBudget
                ) ||
                baseBudget
            );

        const spacing =
            Math.max(
                .16,
                Number(
                    config
                        .candidateSpacing
                ) || .40
            );

        const desiredOutput =
            frameLimitForClip(
                clip,
                config
            );

        const minimumPool =
            Math.min(
                maximumBudget,
                Math.max(
                    3,
                    desiredOutput * 2
                )
            );

        const naturalCount =
            Math.max(
                1,
                Math.ceil(
                    usableDuration /
                    spacing
                )
            );

        let sampleCount =
            Math.max(
                minimumPool,
                naturalCount
            );

        sampleCount =
            clamp(
                sampleCount,
                1,
                maximumBudget
            );

        const times = [];

        for (
            let index = 0;
            index <
                sampleCount;
            index += 1
        ) {

            const fraction =
                (
                    index + .5
                ) /
                sampleCount;

            times.push(
                safeStart +
                usableDuration *
                    fraction
            );
        }

        return [
            ...new Set(
                times.map(
                    time =>
                        Math.round(
                            time * 1000
                        ) /
                        1000
                )
            )
        ].sort(
            (a, b) =>
                a - b
        );
    }

    function denseCandidateTimesForClip(
        clip,
        config,
        oldFrames = [],
        passIndex = 0,
        fpsValue = 25
    ) {
        const safeStart =
            Math.min(
                clip.end,
                Math.max(
                    clip.start + .04,
                    Number.isFinite(
                        clip.transitionEnd
                    )
                        ? clip.transitionEnd +
                            .035
                        : clip.start +
                            .04
                )
            );

        const safeEnd =
            Math.max(
                safeStart,
                clip.end - .04
            );

        const usableDuration =
            safeEnd -
            safeStart;

        const fps =
            clamp(
                Number(fpsValue) || 25,
                8,
                120
            );

        const frameInterval =
            1 / fps;

        if (
            usableDuration <= .06
        ) {
            const middle =
                clamp(
                    clip.start +
                        (
                            clip.end -
                            clip.start
                        ) *
                        .5,
                    clip.start,
                    Math.max(
                        clip.start,
                        clip.end - .01
                    )
                );

            return [
                middle
            ];
        }

        const budget =
            clamp(
                (
                    Number(
                        config
                            .candidateBudget
                    ) || 6
                ) * 3,
                10,
                30
            );

        const denseSpacing =
            clamp(
                (
                    Number(
                        config
                            .candidateSpacing
                    ) || .45
                ) * .38,
                .07,
                .20
            );

        const minimumOldGap =
            Math.max(
                .035,
                frameInterval *
                    1.15
            );

        const oldTimes =
            oldFrames
                .map(
                    frame =>
                        Number(
                            frame.time
                        )
                )
                .filter(
                    time =>
                        Number.isFinite(
                            time
                        )
                );

        const candidates =
            new Map();

        function addCandidate(
            value,
            priority
        ) {
            if (
                !Number.isFinite(
                    value
                )
            ) {
                return;
            }

            const time =
                clamp(
                    value,
                    safeStart,
                    safeEnd
                );

            const alreadyRepresented =
                oldTimes.some(
                    oldTime =>
                        Math.abs(
                            oldTime -
                            time
                        ) <
                        minimumOldGap
                );

            if (
                alreadyRepresented
            ) {
                return;
            }

            const rounded =
                Math.round(
                    time * 1000
                ) /
                1000;

            const key =
                rounded.toFixed(3);

            const previous =
                candidates.get(
                    key
                );

            if (
                !previous ||
                priority <
                    previous.priority
            ) {
                candidates.set(
                    key,
                    {
                        time:
                            rounded,
                        priority
                    }
                );
            }
        }

        const oldBest =
            oldFrames.find(
                frame =>
                    frame.best
            ) ||
            (
                oldFrames.length
                    ? oldFrames.reduce(
                        (
                            best,
                            frame
                        ) =>
                            frame.quality >
                            best.quality
                                ? frame
                                : best,
                        oldFrames[0]
                    )
                    : null
            );

        if (oldBest) {
            const bestStep =
                Math.max(
                    Number(
                        config.bestPass
                            ?.step
                    ) || .10,
                    frameInterval * 2
                );

            [
                -.5,
                .5,
                -1,
                1,
                -1.5,
                1.5,
                -2,
                2
            ].forEach(
                multiplier => {
                    addCandidate(
                        oldBest.time +
                            bestStep *
                            multiplier,
                        0
                    );
                }
            );
        }

        const anchors =
            [
                safeStart,
                ...oldTimes.filter(
                    time =>
                        time >
                            safeStart &&
                        time <
                            safeEnd
                ),
                safeEnd
            ]
                .sort(
                    (a, b) =>
                        a - b
                );

        for (
            let index = 0;
            index <
                anchors.length - 1;
            index += 1
        ) {
            const left =
                anchors[index];

            const right =
                anchors[
                    index + 1
                ];

            const gap =
                right - left;

            if (
                gap >
                minimumOldGap *
                    2.5
            ) {
                addCandidate(
                    left +
                        gap *
                            .5,
                    .5
                );
            }

            if (
                gap >
                denseSpacing *
                    1.4
            ) {
                addCandidate(
                    left +
                        gap /
                            3,
                    1
                );

                addCandidate(
                    left +
                        gap *
                            2 /
                            3,
                    1
                );
            }
        }

        const baseCount =
            clamp(
                Math.ceil(
                    usableDuration /
                        denseSpacing
                ) + 1,
                6,
                budget
            );

        const phase =
            (
                (
                    Math.max(
                        0,
                        passIndex
                    ) %
                    3
                ) +
                1
            ) /
            4;

        for (
            let index = 0;
            index < baseCount;
            index += 1
        ) {
            const fraction =
                (
                    index +
                    phase
                ) /
                baseCount;

            addCandidate(
                safeStart +
                    usableDuration *
                        fraction,
                2
            );
        }

        let selected =
            [
                ...candidates
                    .values()
            ]
                .sort(
                    (a, b) =>
                        a.priority -
                            b.priority ||
                        a.time -
                            b.time
                )
                .slice(
                    0,
                    budget
                )
                .map(
                    item =>
                        item.time
                );

        if (!selected.length) {
            selected = [
                safeStart +
                    usableDuration *
                        (
                            passIndex %
                                2
                                ? .63
                                : .37
                        )
            ];
        }

        return [
            ...new Set(
                selected.map(
                    value =>
                        Math.round(
                            value * 1000
                        ) /
                        1000
                )
            )
        ]
            .sort(
                (a, b) =>
                    a - b
            );
    }

    function framesEquivalentForReanalysis(
        first,
        second,
        config
    ) {
        if (
            !first ||
            !second
        ) {
            return false;
        }

        const distance =
            frameDistances(
                first,
                second
            );

        const timeDistance =
            Math.abs(
                Number(
                    first.time
                ) -
                Number(
                    second.time
                )
            );

        const duplicate =
            config.duplicate ||
            {};

        const visualLimit =
            Math.max(
                .10,
                (
                    Number(
                        duplicate.visual
                    ) || .10
                ) *
                    1.18
            );

        const overlayLimit =
            Math.max(
                .075,
                (
                    Number(
                        duplicate
                            .overlaySignature
                    ) || .065
                ) *
                    1.25
            );

        const histogramLimit =
            Math.max(
                .10,
                (
                    Number(
                        duplicate.histogram
                    ) || .12
                ) *
                    1.15
            );

        const nearbyLimit =
            Math.max(
                .14,
                (
                    Number(
                        duplicate
                            .nearbyVisual
                    ) || .13
                ) *
                    1.08
            );

        return (
            distance.visual <=
                visualLimit ||
            (
                distance
                    .overlaySignature <=
                    overlayLimit &&
                distance.histogram <=
                    histogramLimit
            ) ||
            (
                timeDistance <=
                    Math.max(
                        .28,
                        (
                            Number(
                                config
                                    .minCandidateGap
                            ) || .20
                        ) *
                            1.5
                    ) &&
                distance.visual <=
                    nearbyLimit
            )
        );
    }

    function reanalysisFrameDiversity(
        frame,
        peers
    ) {
        const others =
            peers.filter(
                item =>
                    item &&
                    item.id !==
                        frame.id
            );

        if (!others.length) {
            return .25;
        }

        return Math.min(
            ...others.map(
                item => {
                    const distance =
                        frameDistances(
                            frame,
                            item
                        );

                    return Math.min(
                        distance.visual,
                        distance
                            .overlaySignature *
                            1.65
                    );
                }
            )
        );
    }

    function reanalysisFrameValue(
        frame,
        peers,
        config
    ) {
        const targetDiversity =
            Math.max(
                .08,
                Number(
                    config.minDiversity
                ) || .13
            );

        const diversity =
            clamp(
                reanalysisFrameDiversity(
                    frame,
                    peers
                ) /
                    targetDiversity,
                0,
                1
            );

        const quality =
            clamp(
                Number(
                    frame.quality
                ) || 0,
                0,
                1
            );

        return (
            quality *
                .80 +
            diversity *
                .20
        );
    }
  
    function reconcileReanalyzedFrames(
        oldFrames,
        newFrames,
        config,
        clip = null,
        selectedFrames = null
    ) {
        const oldIds =
            new Set(
                oldFrames.map(
                    frame =>
                        frame.id
                )
            );

        const finalFrames =
            [
                ...oldFrames
            ];

        const replacements =
            [];

        const limit =
            frameLimitForClip(
                clip,
                config,
                [
                    ...oldFrames,
                    ...newFrames
                ]
            );

        const minimumQualityGain =
            .018;

        const minimumValueGain =
            .018;

        const oldBest =
            oldFrames.find(
                frame =>
                    frame.best
            ) ||
            (
                oldFrames.length
                    ? oldFrames.reduce(
                        (
                            best,
                            frame
                        ) =>
                            frame.quality >
                            best.quality
                                ? frame
                                : best,
                        oldFrames[0]
                    )
                    : null
            );

        const manualBest =
            oldFrames.find(
                frame =>
                    frame.manualBest
            ) ||
            null;

        const orderedNew =
            [
                ...newFrames
            ]
                .sort(
                    (a, b) =>
                        b.quality -
                        a.quality
                );

        for (
            const candidate
            of orderedNew
        ) {

            let equivalentIndex =
                -1;

            let nearestDistance =
                Infinity;

            finalFrames.forEach(
                (
                    existing,
                    index
                ) => {
                    if (
                        !framesEquivalentForReanalysis(
                            candidate,
                            existing,
                            config
                        )
                    ) {
                        return;
                    }

                    const distance =
                        frameDistances(
                            candidate,
                            existing
                        );

                    const value =
                        Math.min(
                            distance.visual,
                            distance
                                .overlaySignature *
                                1.65
                        );

                    if (
                        value <
                        nearestDistance
                    ) {
                        nearestDistance =
                            value;

                        equivalentIndex =
                            index;
                    }
                }
            );

            if (
                equivalentIndex >=
                0
            ) {
                const existing =
                    finalFrames[
                        equivalentIndex
                    ];

                if (
                    existing.manualBest
                ) {
                    continue;
                }

                const qualityGain =
                    (
                        Number(
                            candidate.quality
                        ) || 0
                    ) -
                    (
                        Number(
                            existing.quality
                        ) || 0
                    );

                if (
                    qualityGain <
                    minimumQualityGain
                ) {
                    continue;
                }

                candidate.status =
                    existing.status;

                candidate.best =
                    Boolean(
                        existing.best
                    );

                candidate.manualBest =
                    false;

                replacements.push({
                    oldFrame:
                        existing,
                    newFrame:
                        candidate
                });

                finalFrames[
                    equivalentIndex
                ] =
                    candidate;

                continue;
            }

            const currentBest =
                finalFrames.find(
                    frame =>
                        frame.best
                ) ||
                oldBest ||
                finalFrames[0];

            const qualityFloor =
                Math.max(
                    Number(
                        config
                            .minimumCandidateQuality
                    ) || .28,
                    (
                        Number(
                            currentBest
                                ?.quality
                        ) || 0
                    ) -
                    (
                        Number(
                            config
                                .maxQualityDrop
                        ) || .30
                    )
                );

            if (
                Number(
                    candidate.quality
                ) <
                qualityFloor
            ) {
                continue;
            }

            if (
                finalFrames.length <
                limit
            ) {
                finalFrames.push(
                    candidate
                );

                continue;
            }

            const removable =
                finalFrames
                    .map(
                        (
                            frame,
                            index
                        ) => ({
                            frame,
                            index
                        })
                    )
                    .filter(
                        item =>
                            !item.frame
                                .manualBest &&
                            !item.frame
                                .best &&
                            !selectedFrames
                                .has(
                                    item.frame
                                        .id
                                )
                    );

            if (
                !removable.length
            ) {
                continue;
            }

            removable.forEach(
                item => {
                    item.value =
                        reanalysisFrameValue(
                            item.frame,
                            finalFrames.filter(
                                (
                                    _,
                                    index
                                ) =>
                                    index !==
                                    item.index
                            ),
                            config
                        );
                }
            );

            removable.sort(
                (a, b) =>
                    a.value -
                    b.value
            );

            const weakest =
                removable[0];

            const candidateValue =
                reanalysisFrameValue(
                    candidate,
                    finalFrames,
                    config
                );

            const candidateDiversity =
                reanalysisFrameDiversity(
                    candidate,
                    finalFrames
                );

            const weakestDiversity =
                reanalysisFrameDiversity(
                    weakest.frame,
                    finalFrames.filter(
                        (
                            _,
                            index
                        ) =>
                            index !==
                            weakest.index
                    )
                );

            const clearlyBetter =
                candidateValue >=
                weakest.value +
                    minimumValueGain;

            const addsUsefulDiversity =
                candidateDiversity >=
                    weakestDiversity +
                        .055 &&
                Number(
                    candidate.quality
                ) >=
                    Number(
                        weakest.frame
                            .quality
                    ) -
                        .015;

            if (
                clearlyBetter ||
                addsUsefulDiversity
            ) {
                finalFrames[
                    weakest.index
                ] =
                    candidate;
            }
        }

        let chosenBest =
            manualBest &&
            finalFrames.includes(
                manualBest
            )
                ? manualBest
                : (
                    finalFrames.find(
                        frame =>
                            frame.best
                    ) ||
                    oldBest ||
                    finalFrames[0]
                );

        const highestQuality =
            finalFrames.length
                ? finalFrames.reduce(
                    (
                        best,
                        frame
                    ) =>
                        frame.quality >
                        best.quality
                            ? frame
                            : best,
                    finalFrames[0]
                )
                : null;

        if (
            !manualBest &&
            highestQuality &&
            chosenBest &&
            highestQuality.id !==
                chosenBest.id &&
            highestQuality.quality >=
                chosenBest.quality +
                    minimumQualityGain
        ) {
            chosenBest =
                highestQuality;
        }

        if (
            !chosenBest
        ) {
            chosenBest =
                highestQuality;
        }

        finalFrames.forEach(
            frame => {
                frame.best =
                    Boolean(
                        chosenBest &&
                        frame.id ===
                            chosenBest.id
                    );

                if (
                    manualBest
                ) {
                    frame.manualBest =
                        frame.id ===
                        manualBest.id;
                } else {
                    frame.manualBest =
                        false;
                }
            }
        );

        const finalIds =
            new Set(
                finalFrames.map(
                    frame =>
                        frame.id
                )
            );

        const acceptedNew =
            finalFrames.filter(
                frame =>
                    !oldIds.has(
                        frame.id
                    )
            );

        const removedOld =
            oldFrames.filter(
                frame =>
                    !finalIds.has(
                        frame.id
                    )
            );

        const activeReplacements =
            replacements.filter(
                item =>
                    finalIds.has(
                        item.newFrame.id
                    ) &&
                    !finalIds.has(
                        item.oldFrame.id
                    )
            );

        const replacementIds =
            new Set(
                activeReplacements.map(
                    item =>
                        item.newFrame.id
                )
            );

        const distinctNew =
            acceptedNew.filter(
                frame =>
                    !replacementIds.has(
                        frame.id
                    )
            );

        const bestChanged =
            Boolean(
                oldBest &&
                chosenBest &&
                oldBest.id !==
                    chosenBest.id
            );

        return {
            frames:
                finalFrames.sort(
                    (a, b) =>
                        a.time -
                        b.time
                ),

            oldBest,
            newBest:
                chosenBest,

            manualBest:
                manualBest,

            replacements:
                activeReplacements,

            acceptedNew,
            distinctNew,
            removedOld,

            bestChanged,

            changed:
                acceptedNew.length >
                    0 ||
                removedOld.length >
                    0 ||
                bestChanged
        };
    }

    const api = Object.freeze({
        featureFromCanvas,
        isLowLightFeature,
        compareFeatures,
        adaptiveThreshold,
        passesStructuralGate,
        detectSuspiciousRanges,
        normalizeBoundaries,
        averageNumbers,
        boundarySpatialEvidence,
        qualityMetricsFromCanvas,
        frameDistances,
        frameLimitForClip,
        frameAppearanceSimilarity,
        framesShareSameLook,
        clusterFramesByAppearance,
        isUsableFrameCandidate,
        frameSceneAffinity,
        reciprocalClipAffinity,
        candidateTimesForClip,
        denseCandidateTimesForClip,
        framesEquivalentForReanalysis,
        reanalysisFrameDiversity,
        reanalysisFrameValue,
        reconcileReanalyzedFrames
    });

    Object.defineProperty(window, 'VideoLensAnalysisEngine', {
        configurable: false,
        enumerable: false,
        writable: false,
        value: api
    });
})();
